"""
Evaluate the intrinsic radial Gaussian weight of each stationary branch.

The intrinsic Hessian is derived on the nonlinear surface, as in Appendix A. Equations 9 and 17 provide its Gaussian determinant factor. The coupling rescales a tangent space of dimension N-1.

Returns
-------
return result
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

def branch_logweights(branches: "np.ndarray", coupling: float, geometry: "np.ndarray") -> "np.ndarray":
    """Evaluate the intrinsic radial Gaussian weight of each stationary branch.

    branches : ndarray, shape (2,N+1)
        Two rows [K,phi[0],...,phi[N-1]], each stationary for its multiplier.
    coupling : float > 0
        Dimensionless lambda in physical action s/lambda.
    geometry : ndarray, shape (N,4)
        Columns are radius r, positive cell weight w, outward edge c, and stiffness diagonal Ljj; rows run from origin outward. All entries are dimensionless.
    Returns
    -------
    ndarray, shape (2,4)
        Columns [s,nu,log(abs(D)),log(G)] for each input row, preserving input order. D is the intrinsic determinant of s on the cubic-constraint surface in the y metric. G=exp(-s/lambda)/sqrt(abs(det(C/lambda))). Both D values are nonzero.

    Raises
    ------
    ValueError
        If numerical input domains or array shapes are invalid.
    """
    return result

# =============================================================================
# GOLD SOLUTION
# =============================================================================

import numpy as np
from scipy.linalg import solve_banded, eigvalsh_tridiagonal
from scipy.optimize import root, brentq
from scipy.special import logsumexp

def _oracle_branch_logweights(branches: "np.ndarray", coupling: float, geometry: "np.ndarray") -> "np.ndarray":
    branches=np.asarray(branches,dtype=float);geometry=np.asarray(geometry,dtype=float)
    if not np.isfinite(coupling) or coupling<=0 or geometry.ndim!=2 or geometry.shape[1]!=4 or branches.shape!=(2,len(geometry)+1) or not np.all(np.isfinite(branches)):
        raise ValueError("Invalid Gaussian-weight inputs")
    rows=[]
    for branch in branches:
        k=branch[0];p=branch[1:]
        jet=_oracle_action_jet(p,k,geometry)
        response=_oracle_normal_response(jet,p,geometry)
        logdet=response[3]+np.log(abs(response[1]))
        # The action is s/lambda, so the tangent Hessian has N-1 factors of 1/lambda.
        logweight=-jet[0]/coupling-.5*(logdet-(len(p)-1)*np.log(coupling))
        rows.append([jet[0],response[1],logdet,logweight])
    return np.array(rows)

